def zero_components(grid):
    """The 4-connected components of background (0) cells, as lists of (row, col)."""
    h, w = len(grid), len(grid[0])
    seen, comps = set(), []
    for i in range(h):
        for j in range(w):
            if grid[i][j] == 0 and (i, j) not in seen:
                stack, cells = [(i, j)], []
                seen.add((i, j))
                while stack:
                    y, x = stack.pop(); cells.append((y, x))
                    for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny, nx = y+dy, x+dx
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0 and (ny, nx) not in seen:
                            seen.add((ny, nx)); stack.append((ny, nx))
                comps.append(cells)
    return comps

def paint(cells, grid, color):
    """Set every (row, col) cell in cells of grid to color (returns a copy)."""
    out = [row[:] for row in grid]
    for y, x in cells:
        out[y][x] = color
    return out

def fill_extreme_zero_regions(grid, hi=8, lo=7):
    """The largest zero-region recolored hi and the smallest recolored lo; other regions unchanged."""
    comps = zero_components(grid)
    if not comps:
        return [row[:] for row in grid]
    out = paint(max(comps, key=len), grid, hi)
    return paint(min(comps, key=len), out, lo)
